import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def parse_version(s):
    if not isinstance(s, str):
        raise ValueError

    m = _VERSION_RE.fullmatch(s)
    if not m:
        raise ValueError

    major, minor, patch = map(int, m.group(1, 2, 3))
    pre_str = m.group(4)
    pre = ()

    if pre_str is not None:
        parts = pre_str.split(".")
        for part in parts:
            if part == "":
                raise ValueError
            if part.isdigit() and len(part) > 1 and part[0] == "0":
                raise ValueError
        pre = tuple(parts)

    return (major, minor, patch, pre)


def cmp_versions(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    a_pre = a[3]
    b_pre = b[3]

    if a_pre and not b_pre:
        return -1
    if not a_pre and b_pre:
        return 1
    if not a_pre and not b_pre:
        return 0

    for x, y in zip(a_pre, b_pre):
        x_num = x.isdigit()
        y_num = y.isdigit()

        if x_num and y_num:
            ix = int(x)
            iy = int(y)
            if ix != iy:
                return -1 if ix < iy else 1
        elif x_num:
            return -1
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a_pre) != len(b_pre):
        return -1 if len(a_pre) < len(b_pre) else 1

    return 0


def caret_upper(v):
    major, minor, patch, _ = v
    if major > 0:
        return (major + 1, 0, 0, ())
    if minor > 0:
        return (0, minor + 1, 0, ())
    return (0, 0, patch + 1, ())


def tilde_upper(v):
    major, minor, patch, _ = v
    return (major, minor + 1, 0, ())


def parse_comparator(token):
    if not token:
        raise ValueError

    if token[0] in "0123456789":
        op = "eq"
        ver = token
    elif token[0] == "=":
        op = "eq"
        ver = token[1:]
    elif token[0] == ">":
        if len(token) > 1 and token[1] == "=":
            op = "gte"
            ver = token[2:]
        else:
            op = "gt"
            ver = token[1:]
    elif token[0] == "<":
        if len(token) > 1 and token[1] == "=":
            op = "lte"
            ver = token[2:]
        else:
            op = "lt"
            ver = token[1:]
    elif token[0] == "^":
        op = "caret"
        ver = token[1:]
    elif token[0] == "~":
        op = "tilde"
        ver = token[1:]
    else:
        raise ValueError

    if not ver:
        raise ValueError

    return (op, parse_version(ver))


def parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError

    sets = []
    for part in rng.split("||"):
        part = part.strip()
        if not part:
            raise ValueError

        comparators = []
        for token in part.split():
            comparators.append(parse_comparator(token))

        if not comparators:
            raise ValueError

        sets.append(comparators)

    if not sets:
        raise ValueError

    return sets


def comparator_satisfied(version, comparator):
    op, target = comparator
    c = cmp_versions(version, target)

    if op == "eq":
        return c == 0
    if op == "gt":
        return c > 0
    if op == "gte":
        return c >= 0
    if op == "lt":
        return c < 0
    if op == "lte":
        return c <= 0
    if op == "caret":
        return c >= 0 and cmp_versions(version, caret_upper(target)) < 0
    if op == "tilde":
        return c >= 0 and cmp_versions(version, tilde_upper(target)) < 0

    raise ValueError


def prerelease_rule_satisfied(version, comparators):
    if not version[3]:
        return True

    for _, target in comparators:
        if (
            version[:3] == target[:3]
            and target[3]
        ):
            return True

    return False


def satisfies(version, rng):
    v = parse_version(version)
    range_sets = parse_range(rng)

    for comparators in range_sets:
        if all(comparator_satisfied(v, c) for c in comparators):
            if prerelease_rule_satisfied(v, comparators):
                return True

    return False
