from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    def parse_field(field, lo, hi):
        if field == "*":
            return set(range(lo, hi + 1))

        values = set()
        items = field.split(",")

        for item in items:
            if not item:
                raise ValueError

            if item == "*":
                values.update(range(lo, hi + 1))
                continue

            if item.startswith("*"):
                rest = item[1:]
                if not rest.startswith("/"):
                    raise ValueError
                step_str = rest[1:]
                if not step_str.isdigit():
                    raise ValueError
                step = int(step_str)
                if step < 1:
                    raise ValueError
                values.update(range(lo, hi + 1, step))
                continue

            if "/" in item:
                base, step_str = item.split("/", 1)
                if "/" in step_str:
                    raise ValueError
                if not step_str.isdigit():
                    raise ValueError
                step = int(step_str)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = 1

            if not base:
                raise ValueError

            if "-" in base:
                parts = base.split("-", 1)
                if len(parts) != 2 or "-" in parts[1]:
                    raise ValueError
                a_str, b_str = parts
                if not a_str.isdigit() or not b_str.isdigit():
                    raise ValueError
                a = int(a_str)
                b = int(b_str)
                if a < lo or a > hi or b < lo or b > hi:
                    raise ValueError
                if a > b:
                    raise ValueError
                start, end = a, b
            else:
                if not base.isdigit():
                    raise ValueError
                n = int(base)
                if n < lo or n > hi:
                    raise ValueError
                start, end = n, hi

            values.update(range(start, end + 1, step))

        return values

    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    doms = parse_field(dom_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7)

    if 7 in dows:
        dows.add(0)
        dows.discard(7)

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = ((dt.weekday() + 1) % 7) in dows
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    candidate = after.replace(second=0, microsecond=0)
    if candidate <= after:
        candidate += timedelta(minutes=1)

    limit = after + timedelta(days=3000)

    while candidate <= limit:
        if candidate.month not in months:
            if candidate.month == 12:
                candidate = datetime(candidate.year + 1, 1, 1)
            else:
                candidate = datetime(candidate.year, candidate.month + 1, 1)
            continue

        if not day_matches(candidate):
            candidate = candidate.replace(hour=0, minute=0) + timedelta(days=1)
            continue

        if candidate.hour not in hours:
            candidate = candidate.replace(minute=0) + timedelta(hours=1)
            continue

        if candidate.minute not in minutes:
            candidate += timedelta(minutes=1)
            continue

        return candidate

    raise ValueError
