import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    def parse_pointer(path, allow_dash=False):
        if not isinstance(path, str):
            raise PatchError
        if path == "":
            return []
        if not path.startswith("/"):
            raise PatchError

        raw_tokens = path[1:].split("/")
        tokens = []
        for raw in raw_tokens:
            token = []
            i = 0
            while i < len(raw):
                c = raw[i]
                if c == "~":
                    if i + 1 >= len(raw):
                        raise PatchError
                    nxt = raw[i + 1]
                    if nxt == "0":
                        token.append("~")
                    elif nxt == "1":
                        token.append("/")
                    else:
                        raise PatchError
                    i += 2
                else:
                    token.append(c)
                    i += 1
            tokens.append("".join(token))

        if not allow_dash:
            for i, token in enumerate(tokens):
                if token == "-" and i != len(tokens) - 1:
                    raise PatchError

        return tokens

    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def is_bool(x):
        return isinstance(x, bool)

    def json_equal(a, b):
        if is_bool(a) or is_bool(b):
            if is_bool(a) and is_bool(b):
                return a == b
            return False

        if is_number(a) and is_number(b):
            return a == b

        if isinstance(a, list) and isinstance(b, list):
            if len(a) != len(b):
                return False
            return all(json_equal(x, y) for x, y in zip(a, b))

        if isinstance(a, dict) and isinstance(b, dict):
            if set(a.keys()) != set(b.keys()):
                return False
            return all(json_equal(a[k], b[k]) for k in a)

        if a is None and b is None:
            return True

        if isinstance(a, str) and isinstance(b, str):
            return a == b

        return False

    def get_existing(container, tokens):
        cur = container
        for token in tokens:
            if isinstance(cur, dict):
                if token not in cur:
                    raise PatchError
                cur = cur[token]
            elif isinstance(cur, list):
                if token == "-":
                    raise PatchError
                if not token.isdigit():
                    raise PatchError
                if len(token) > 1 and token[0] == "0":
                    raise PatchError
                idx = int(token)
                if idx < 0 or idx >= len(cur):
                    raise PatchError
                cur = cur[idx]
            else:
                raise PatchError
        return cur

    def add_at(container, tokens, value):
        if not tokens:
            return value

        parent_tokens = tokens[:-1]
        final = tokens[-1]

        if parent_tokens:
            parent = get_existing(container, parent_tokens)
        else:
            parent = container

        if isinstance(parent, dict):
            parent[final] = value
        elif isinstance(parent, list):
            if final == "-":
                parent.append(value)
            else:
                if not final.isdigit():
                    raise PatchError
                if len(final) > 1 and final[0] == "0":
                    raise PatchError
                idx = int(final)
                if idx < 0 or idx > len(parent):
                    raise PatchError
                parent.insert(idx, value)
        else:
            raise PatchError

        return container

    def remove_at(container, tokens):
        if not tokens:
            raise PatchError

        parent_tokens = tokens[:-1]
        final = tokens[-1]

        if parent_tokens:
            parent = get_existing(container, parent_tokens)
        else:
            parent = container

        if isinstance(parent, dict):
            if final not in parent:
                raise PatchError
            del parent[final]
        elif isinstance(parent, list):
            if final == "-":
                raise PatchError
            if not final.isdigit():
                raise PatchError
            if len(final) > 1 and final[0] == "0":
                raise PatchError
            idx = int(final)
            if idx < 0 or idx >= len(parent):
                raise PatchError
            del parent[idx]
        else:
            raise PatchError

        return container

    def replace_at(container, tokens, value):
        if not tokens:
            return value

        parent_tokens = tokens[:-1]
        final = tokens[-1]

        if parent_tokens:
            parent = get_existing(container, parent_tokens)
        else:
            parent = container

        if isinstance(parent, dict):
            if final not in parent:
                raise PatchError
            parent[final] = value
        elif isinstance(parent, list):
            if final == "-":
                raise PatchError
            if not final.isdigit():
                raise PatchError
            if len(final) > 1 and final[0] == "0":
                raise PatchError
            idx = int(final)
            if idx < 0 or idx >= len(parent):
                raise PatchError
            parent[idx] = value
        else:
            raise PatchError

        return container

    def is_proper_descendant(source_tokens, target_tokens):
        return (
            len(target_tokens) > len(source_tokens)
            and target_tokens[:len(source_tokens)] == source_tokens
        )

    result = copy.deepcopy(doc)

    for op in ops:
        if not isinstance(op, dict):
            raise PatchError

        if "op" not in op or "path" not in op:
            raise PatchError

        kind = op["op"]
        path_tokens = parse_pointer(op["path"], allow_dash=(kind in ("add", "move", "copy")))

        if kind == "add":
            if "value" not in op:
                raise PatchError
            value = copy.deepcopy(op["value"])
            result = add_at(result, path_tokens, value)

        elif kind == "remove":
            if path_tokens:
                get_existing(result, path_tokens)
            else:
                raise PatchError
            result = remove_at(result, path_tokens)

        elif kind == "replace":
            if "value" not in op:
                raise PatchError
            value = copy.deepcopy(op["value"])
            result = replace_at(result, path_tokens, value)

        elif kind == "move":
            if "from" not in op:
                raise PatchError
            from_tokens = parse_pointer(op["from"], allow_dash=False)

            if is_proper_descendant(from_tokens, path_tokens):
                raise PatchError

            value = get_existing(result, from_tokens)

            if from_tokens == path_tokens:
                continue

            result = remove_at(result, from_tokens)
            result = add_at(result, path_tokens, value)

        elif kind == "copy":
            if "from" not in op:
                raise PatchError
            from_tokens = parse_pointer(op["from"], allow_dash=False)

            value = copy.deepcopy(get_existing(result, from_tokens))
            result = add_at(result, path_tokens, value)

        elif kind == "test":
            if "value" not in op:
                raise PatchError
            target = get_existing(result, path_tokens)
            if not json_equal(target, op["value"]):
                raise PatchError

        else:
            raise PatchError

    return result
