class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    nodes = set(deps)
    dep_edges = {}

    for target, ds in deps.items():
        seen = set()
        unique_deps = []
        for d in ds:
            nodes.add(d)
            if d not in seen:
                seen.add(d)
                unique_deps.append(d)
        dep_edges[target] = sorted(unique_deps)

    def normalize_cycle(cycle):
        unique = cycle[:-1]
        if not unique:
            return cycle
        min_idx = min(range(len(unique)), key=lambda i: unique[i])
        unique = unique[min_idx:] + unique[:min_idx]
        return unique + [unique[0]]

    color = {node: 0 for node in nodes}
    path = []
    path_index = {}

    for start in sorted(nodes):
        if color[start] != 0:
            continue

        color[start] = 1
        path.append(start)
        path_index[start] = len(path) - 1
        stack = [(start, iter(dep_edges.get(start, ())))]

        while stack:
            u, it = stack[-1]
            try:
                v = next(it)
            except StopIteration:
                stack.pop()
                color[u] = 2
                path.pop()
                del path_index[u]
                continue

            if color[v] == 0:
                color[v] = 1
                path.append(v)
                path_index[v] = len(path) - 1
                stack.append((v, iter(dep_edges.get(v, ()))))
            elif color[v] == 1:
                idx = path_index[v]
                cycle = path[idx:] + [v]
                raise CycleError(normalize_cycle(cycle))

    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    for target, ds in dep_edges.items():
        for d in ds:
            dependents[d].append(target)
            indegree[target] += 1

    import heapq

    heap = [node for node, deg in indegree.items() if deg == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in dependents[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    return order
