def glob_match(pattern, path):
    """Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    def find_set_end(pat, start):
        i = start + 1
        if i < len(pat) and pat[i] == "!":
            i += 1
        first = True
        while i < len(pat):
            if pat[i] == "]" and not first:
                return i + 1
            first = False
            i += 1
        raise ValueError("unterminated [ in pattern")

    def split_pattern_segments(pat):
        segments = []
        cur = []
        i = 0
        while i < len(pat):
            ch = pat[i]
            if ch == "\\":
                if i + 1 >= len(pat):
                    raise ValueError("trailing lone backslash in pattern")
                cur.append(ch)
                cur.append(pat[i + 1])
                i += 2
            elif ch == "[":
                end = find_set_end(pat, i)
                cur.extend(pat[i:end])
                i = end
            elif ch == "/":
                segments.append("".join(cur))
                cur = []
                i += 1
            else:
                cur.append(ch)
                i += 1
        segments.append("".join(cur))
        return segments

    def parse_set(pat, start, end):
        i = start + 1
        neg = False
        if i < end and pat[i] == "!":
            neg = True
            i += 1

        members = []
        ranges = []
        first = True

        while i < end:
            if pat[i] == "]" and not first:
                break

            c = pat[i]
            i += 1

            if first and c == "-":
                members.append(c)
                first = False
                continue

            if i < end and pat[i] == "-" and i + 1 < end and pat[i + 1] != "]":
                d = pat[i + 1]
                ranges.append((c, d))
                i += 2
            else:
                members.append(c)

            first = False

        return neg, members, ranges

    def set_matcher(neg, members, ranges):
        member_set = set(members)

        def match_char(ch):
            if ch == "/":
                return False
            in_set = ch in member_set
            if not in_set:
                for lo, hi in ranges:
                    if lo <= ch <= hi:
                        in_set = True
                        break
            return not in_set if neg else in_set

        return match_char

    def tokenize_segment(seg):
        tokens = []
        i = 0
        while i < len(seg):
            ch = seg[i]
            if ch == "\\":
                if i + 1 >= len(seg):
                    raise ValueError("trailing lone backslash in pattern")
                tokens.append(("lit", seg[i + 1]))
                i += 2
            elif ch == "?":
                tokens.append(("any",))
                i += 1
            elif ch == "*":
                tokens.append(("star",))
                i += 1
            elif ch == "[":
                end = find_set_end(seg, i)
                neg, members, ranges = parse_set(seg, i, end)
                tokens.append(("set", set_matcher(neg, members, ranges)))
                i = end
            else:
                tokens.append(("lit", ch))
                i += 1
        return tokens

    def match_segment(tokens, text):
        n = len(text)
        possible = [False] * (n + 1)
        possible[0] = True

        for token in tokens:
            kind = token[0]
            nxt = [False] * (n + 1)

            if kind == "star":
                seen = False
                for pos in range(n + 1):
                    if possible[pos]:
                        seen = True
                    if seen:
                        nxt[pos] = True
                possible = nxt
            elif kind == "lit":
                ch = token[1]
                for pos in range(n):
                    if possible[pos] and text[pos] == ch:
                        nxt[pos + 1] = True
                possible = nxt
            elif kind == "any":
                for pos in range(n):
                    if possible[pos] and text[pos] != "/":
                        nxt[pos + 1] = True
                possible = nxt
            elif kind == "set":
                matcher = token[1]
                for pos in range(n):
                    if possible[pos] and matcher(text[pos]):
                        nxt[pos + 1] = True
                possible = nxt

        return possible[n]

    pattern_segments = split_pattern_segments(pattern)
    path_segments = path.split("/")

    dp = [False] * (len(path_segments) + 1)
    dp[0] = True

    for seg in pattern_segments:
        nxt = [False] * (len(path_segments) + 1)

        if seg == "**":
            seen = False
            for j in range(len(path_segments) + 1):
                if dp[j]:
                    seen = True
                if seen:
                    nxt[j] = True
        else:
            tokens = tokenize_segment(seg)
            for j in range(len(path_segments)):
                if dp[j] and match_segment(tokens, path_segments[j]):
                    nxt[j + 1] = True

        dp = nxt

    return dp[len(path_segments)]
