from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    def is_digits(s):
        return s != "" and all(c in "0123456789" for c in s)

    def parse_item(item, lo, hi):
        if "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError
            base, step_s = parts
            if not is_digits(step_s):
                raise ValueError
            step = int(step_s)
            if step < 1:
                raise ValueError
            has_step = True
        else:
            base = item
            step = 1
            has_step = False

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            parts = base.split("-")
            if len(parts) != 2:
                raise ValueError
            a_s, b_s = parts
            if not is_digits(a_s) or not is_digits(b_s):
                raise ValueError
            a, b = int(a_s), int(b_s)
            if a < lo or a > hi or b < lo or b > hi:
                raise ValueError
            if a > b:
                raise ValueError
            start, end = a, b
        else:
            if not is_digits(base):
                raise ValueError
            n = int(base)
            if n < lo or n > hi:
                raise ValueError
            start = n
            end = hi if has_step else n

        return set(range(start, end + 1, step))

    def parse_field(field, lo, hi):
        items = field.split(",")
        if any(item == "" for item in items):
            raise ValueError

        values = set()
        for item in items:
            values.update(parse_item(item, lo, hi))

        return values, field == "*"

    minute_set, minute_unrestricted = parse_field(fields[0], 0, 59)
    hour_set, hour_unrestricted = parse_field(fields[1], 0, 23)
    dom_set, dom_unrestricted = parse_field(fields[2], 1, 31)
    month_set, month_unrestricted = parse_field(fields[3], 1, 12)
    dow_set, dow_unrestricted = parse_field(fields[4], 0, 7)

    dow_set = {0 if v == 7 else v for v in dow_set}

    minutes = sorted(minute_set)
    hours = sorted(hour_set)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    current_date = start.date()
    end_date = limit.date()

    while current_date <= end_date:
        if current_date.month in month_set:
            dom_ok = current_date.day in dom_set
            dow_ok = ((current_date.weekday() + 1) % 7) in dow_set

            if dom_unrestricted and dow_unrestricted:
                day_ok = True
            elif dom_unrestricted:
                day_ok = dow_ok
            elif dow_unrestricted:
                day_ok = dom_ok
            else:
                day_ok = dom_ok or dow_ok

            if day_ok:
                for hour in hours:
                    for minute in minutes:
                        candidate = datetime(
                            current_date.year,
                            current_date.month,
                            current_date.day,
                            hour,
                            minute,
                        )
                        if candidate >= start and candidate <= limit:
                            return candidate

        current_date += timedelta(days=1)

    raise ValueError
