import heapq
import sys


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    nodes = set(deps)
    for target, dependencies in deps.items():
        nodes.update(dependencies)

    dependency_edges = {}
    dependents = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for target in nodes:
        unique_dependencies = set(deps.get(target, ()))
        dependency_edges[target] = sorted(unique_dependencies)
        indegree[target] = len(unique_dependencies)
        for dependency in unique_dependencies:
            dependents[dependency].append(target)

    cycle = _find_cycle(nodes, dependency_edges)
    if cycle is not None:
        raise CycleError(_normalize_cycle(cycle))

    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    return order


def _find_cycle(nodes, dependency_edges):
    state = {node: 0 for node in nodes}

    for start in sorted(nodes):
        if state[start] != 0:
            continue

        stack = [start]
        state[start] = 1
        iterators = {start: iter(dependency_edges[start])}

        while stack:
            node = stack[-1]
            try:
                dependency = next(iterators[node])
            except StopIteration:
                state[node] = 2
                stack.pop()
                continue

            if state[dependency] == 1:
                index = stack.index(dependency)
                return stack[index:] + [dependency]

            if state[dependency] == 0:
                state[dependency] = 1
                stack.append(dependency)
                iterators[dependency] = iter(dependency_edges[dependency])

    return None


def _normalize_cycle(cycle):
    nodes = cycle[:-1]
    smallest = min(nodes)
    index = nodes.index(smallest)
    rotated = nodes[index:] + nodes[:index]
    return rotated + [rotated[0]]
